import React, { useState } from 'react';
import GameList from './components/GameList';
import RentGame from './components/RentGame';
import PurchaseGame from './components/PurchaseGame';
import ReviewGame from './components/ReviewGame';
import './App.css';

const API = 'http://localhost:5000/api';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('games');
  const [authMode, setAuthMode] = useState('login');
  const [form, setForm] = useState({ fullName: '', email: '', password: '' });
  const [error, setError] = useState('');

  const handleAuth = async (e) => {
    e.preventDefault();
    setError('');
    const endpoint = authMode === 'login' ? '/users/login' : '/users/register';
    try {
      const res = await fetch(`${API}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || data.error || 'Failed');
      if (authMode === 'login') {
        setUser(data.user || data);
        setPage('games');
      } else {
        setAuthMode('login');
        setError('Registered! Please login.');
      }
    } catch (err) {
      setError(err.message);
    }
  };

  if (!user) {
    return (
      <div style={{ maxWidth: 400, margin: '80px auto', padding: '0 1rem' }}>
        <h1 style={{ textAlign: 'center', marginBottom: '1.5rem' }}>🎮 GameVault</h1>
        <div style={{ background: '#1a1a2e', padding: '2rem', borderRadius: 12 }}>
          <div style={{ display: 'flex', marginBottom: '1.5rem', gap: '1rem' }}>
            <button onClick={() => setAuthMode('login')} style={authMode === 'login' ? activeTab : tab}>Login</button>
            <button onClick={() => setAuthMode('register')} style={authMode === 'register' ? activeTab : tab}>Register</button>
          </div>
          {error && <p style={{ color: '#fc8181', marginBottom: '1rem', fontSize: '0.875rem' }}>{error}</p>}
          <form onSubmit={handleAuth}>
            {authMode === 'register' && (
              <input style={input} placeholder="Full Name" value={form.fullName}
                onChange={e => setForm({ ...form, fullName: e.target.value })} required />
            )}
            <input style={input} type="email" placeholder="Email" value={form.email}
              onChange={e => setForm({ ...form, email: e.target.value })} required />
            <input style={input} type="password" placeholder="Password" value={form.password}
              onChange={e => setForm({ ...form, password: e.target.value })} required />
            <button type="submit" style={primaryBtn}>{authMode === 'login' ? 'Login' : 'Register'}</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: 1100, margin: '0 auto', padding: '0 1rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1rem 0', borderBottom: '1px solid #333', marginBottom: '1.5rem' }}>
        <h2 style={{ color: '#00d4ff' }}>🎮 GameVault</h2>
        <nav style={{ display: 'flex', gap: '0.5rem' }}>
          {['games', 'rent', 'purchase', 'review'].map(p => (
            <button key={p} onClick={() => setPage(p)} style={page === p ? activeTab : tab}>
              {p.charAt(0).toUpperCase() + p.slice(1)}
            </button>
          ))}
        </nav>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <span style={{ color: '#aaa', fontSize: '0.875rem' }}>👤 {user.fullName}</span>
          <button onClick={() => { setUser(null); setPage('games'); }} style={{ ...tab, fontSize: '0.8rem' }}>Logout</button>
        </div>
      </div>

      {page === 'games' && <GameList user={user} />}
      {page === 'rent' && <RentGame user={user} />}
      {page === 'purchase' && <PurchaseGame user={user} />}
      {page === 'review' && <ReviewGame user={user} />}
    </div>
  );
}

const input = {
  display: 'block', width: '100%', marginBottom: '1rem', padding: '0.65rem 1rem',
  background: '#0f0f1a', border: '1px solid #333', borderRadius: 8,
  color: '#fff', fontSize: '0.9rem', boxSizing: 'border-box'
};
const tab = {
  background: 'none', border: '1px solid #333', color: '#aaa',
  padding: '0.4rem 1rem', borderRadius: 8, cursor: 'pointer', fontSize: '0.875rem'
};
const activeTab = { ...tab, borderColor: '#00d4ff', color: '#00d4ff' };
const primaryBtn = {
  width: '100%', padding: '0.65rem', background: '#00d4ff', color: '#000',
  border: 'none', borderRadius: 8, fontWeight: 700, cursor: 'pointer', fontSize: '0.95rem'
};

export default App;
